const D = { energy: .6, scale: 1, density: .5, decay: .5, speed: 1, hue: 206, x: .5, y: .58, alpha: 1, style: 'steel', act: 'drift', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:(v>b?b:v), md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const sd=P.seed|0;
const fr=i=>{const s=Math.sin(i*127.1+sd*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lb==null||K.beat<S.lb)S.lb=K.beat; S.lb=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style;
const sche=(sty==='schematic'), xr=(sty==='xray'), lag=(sty==='lagged'), ox=(sty==='oxide');
const H=md(P.hue,360), AL=cl(P.alpha,0,1);
const en=cl(P.energy,0,1), sc=cl(P.scale,.3,2.4), dens=cl(P.density,0,1);
const spd=cl(P.speed,.1,4), dec=cl(P.decay,0,1.4), act=P.act;
const ax=cl(P.x,.05,.95)*W, ay=cl(P.y,.12,.98)*Hh;
const BH=u*.50*sc;
const NR=Math.max(2,Math.round(3+dens*5));
const slot=BH/NR;

S.bass=(S.bass||0)*.85+(A.bass||0)*.15;
S.tre =(S.tre ||0)*.85+(A.treble||0)*.15;
const T=K.t*spd;
const glow=(.30+.80*en)*(.55+.5*K.intensity)+S.bass*.35;
const kick=Math.min(1,K.pulse*(.5+.5*K.intensity)+S.bass*.7);

// ---- the light: three incommensurate rates, periods 46s / 20s / 12s --------
// it never returns to the same place, so the 8s motion gate always sees a change
let sweep=.62*Math.sin(T*.137)+.28*Math.sin(T*.311+1.7)+.13*Math.sin(T*.523);
let elev=.5+.30*Math.sin(T*.089+.6)+.13*Math.sin(T*.197+2.2);
if(act==='cold'){ sweep*=.55; elev=.5+.16*Math.sin(T*.061); }
const lx=ax+sweep*W*.66;
// a mast off-frame throws a hard shadow the other way
const shx=ax-sweep*W*.80+W*.14*Math.sin(T*.041+2.4);
const shw=W*(.10+.05*Math.sin(T*.073));

// ---- seeded run layout ----------------------------------------------------
function layout(){
  const rs=[];
  for(let i=0;i<NR;i++){
    const dep=fr(i*5.1);
    const y=ay-BH*.5+(i+.5)*slot+(fr(i*5.1+1)-.5)*slot*.26;
    const dia=Math.max(2.5, slot*(.40+.42*fr(i*5.1+2))*(1.06-.34*dep));
    rs.push({ y:y, dia:dia, dep:dep,
      lag:(lag? fr(i*5.1+3)>.22 : fr(i*5.1+3)>.74),
      nf:1+Math.round(fr(i*5.1+5)*3),
      el:fr(i*5.1+6), vent:fr(i*5.1+7) });
  }
  return rs;
}

const bkey=[W,Hh,sty,sd,Math.round(H),Math.round(sc*40),NR,Math.round(dec*6),Math.round(P.x*120),Math.round(P.y*120)].join('|');
if(!S.base||S.bk!==bkey||S.base.width!==W||S.base.height!==Hh){
  const g=(S.base&&S.base.width===W&&S.base.height===Hh)?S.base:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const rs=layout(); S.runs=rs;

  for(let i=0;i<rs.length;i++){
    const r=rs[i], y=r.y, dia=r.dia, near=1-r.dep;
    const lgd=r.lag;
    const hue=lgd?md(H+8,360):(ox?md(H-172,360):H);

    if(sche){
      // P&ID: no mass at all — a double line, valve bowties, tag bubbles
      g.strokeCap(SQUARE);
      g.strokeWeight(Math.max(.8,dia*.10));
      g.stroke(194,64,88,58);
      g.line(0,y-dia*.5,W,y-dia*.5); g.line(0,y+dia*.5,W,y+dia*.5);
      g.strokeWeight(Math.max(.6,dia*.05)); g.stroke(194,50,60,26);
      g.line(0,y,W,y);
      for(let k=0;k<r.nf+1;k++){
        const vx=W*(.10+.80*fr(i*9+k));
        g.noStroke(); g.fill(240,40,10,90);
        g.rect(vx-dia*.7,y-dia*.8,dia*1.4,dia*1.6);
        g.stroke(194,64,92,80); g.strokeWeight(Math.max(.8,dia*.09)); g.noFill();
        g.beginShape();
        g.vertex(vx-dia*.55,y-dia*.5); g.vertex(vx+dia*.55,y+dia*.5);
        g.vertex(vx+dia*.55,y-dia*.5); g.vertex(vx-dia*.55,y+dia*.5);
        g.endShape(CLOSE);
        g.line(vx,y-dia*.5,vx,y-dia*1.5);
        g.ellipse(vx,y-dia*2.0,dia*1.05,dia*1.05);
        g.strokeWeight(Math.max(.5,dia*.05));
        g.line(vx-dia*.5,y-dia*2.0,vx+dia*.5,y-dia*2.0);
      }
      // dashed instrument runs dropping away from the header
      g.strokeWeight(Math.max(.5,dia*.05)); g.stroke(194,40,70,34);
      for(let k=0;k<6;k++){
        const dx=W*fr(i*9+40+k);
        for(let q=0;q<7;q++) g.line(dx,y+dia*(.6+q*.42),dx,y+dia*(.82+q*.42));
      }
      g.noStroke();
      continue;
    }

    // ---- cylindrical body, built from strips (cached, so strips are free) --
    const NS=22;
    for(let k=0;k<NS;k++){
      const q=k/(NS-1);
      const f=Math.max(0,Math.cos((q-.34)*Math.PI*1.16));
      const bounce=Math.max(0,Math.cos((q-.95)*Math.PI*3.4))*.55;
      let s,b;
      if(xr){ s=0; b=5+64*Math.pow(1-f,1.5)+10*bounce; }
      else if(lgd){ s=4+3*(1-near); b=(26+30*f+8*bounce)*(.55+.55*near); }
      else if(ox){ s=24+14*f; b=(6+26*f+9*bounce)*(.5+.6*near); }
      else { s=8+9*(1-near)+5*f; b=(9+48*f+16*bounce)*(.5+.62*near); }
      g.fill(hue,cl(s,0,60),cl(b,2,94),100);
      g.rect(-2,y-dia*.5+q*dia,W+4,dia/NS+1.4);
    }
    // hard terminator top + bottom so the tube reads as a cylinder, not a bar
    g.fill(hue,xr?0:16,xr?70:4,xr?40:52);
    g.rect(-2,y-dia*.5,W+4,Math.max(.8,dia*.055));
    g.fill(hue,xr?0:14,xr?58:6,xr?30:34);
    g.rect(-2,y+dia*.5-Math.max(.8,dia*.05),W+4,Math.max(.8,dia*.05));

    // ---- texture: mill scale, grain, chalk. never a flat fill --------------
    const NG=Math.round((30+dens*26)*(1+dec*.7));
    for(let k=0;k<NG;k++){
      const gx=fr(i*17+k*.37)*W, q=fr(i*17+k*.37+1);
      const gy=y-dia*.5+q*dia, gw=dia*(.5+fr(i*17+k*.37+2)*3.4), gh=Math.max(.7,dia*.035);
      const up=fr(i*17+k*.37+3)>.5;
      g.fill(hue,xr?0:(lgd?3:10),up?(xr?86:74):(xr?12:8),xr?12:(lgd?11:15));
      g.rect(gx,gy,gw,gh);
    }
    if(lgd){
      // aluminium jacket: banded cladding, seams every so often, pop rivets
      const per=Math.max(dia*1.5,W*.06), nb=Math.ceil(W/per)+1;
      for(let k=0;k<nb;k++){
        const bx=k*per+fr(i*11)*per;
        g.fill(hue,5,66,26); g.rect(bx,y-dia*.5,Math.max(1,dia*.05),dia);
        g.fill(hue,4,14,22); g.rect(bx+dia*.05,y-dia*.5,Math.max(1,dia*.04),dia);
        for(let q=0;q<4;q++){
          const ry=y-dia*.34+q*dia*.23;
          g.fill(hue,3,74,34); g.ellipse(bx-dia*.10,ry,dia*.07,dia*.07);
        }
      }
    } else if(!xr){
      // welded seams: a raised bead every few metres of run
      for(let k=0;k<3;k++){
        const bx=W*fr(i*13+k);
        g.fill(hue,10,ox?32:56,30); g.rect(bx,y-dia*.5,Math.max(1,dia*.07),dia);
        g.fill(hue,12,6,26); g.rect(bx+dia*.07,y-dia*.5,Math.max(1,dia*.05),dia);
      }
    } else {
      // radiograph: weld beads read as bright absorption bands across the bore
      for(let k=0;k<4;k++){
        const bx=W*fr(i*13+k);
        g.fill(0,0,92,30); g.rect(bx-dia*.06,y-dia*.5,Math.max(1.4,dia*.12),dia);
        g.fill(0,0,0,26); g.rect(bx+dia*.06,y-dia*.5,Math.max(1,dia*.05),dia);
      }
    }

    // ---- flanges: bolted joints, the punctuation of a pipe run -------------
    for(let k=0;k<r.nf;k++){
      const fx=W*(.08+.84*fr(i*7+k*1.7));
      const fw=Math.max(2,dia*.22), fh=dia*1.30;
      if(xr){
        g.fill(0,0,88,42); g.rect(fx-fw,y-fh*.5,fw*2,fh);
        for(let q=0;q<7;q++){ g.fill(0,0,4,60);
          g.ellipse(fx,y-fh*.42+q*fh*.14,fw*.5,fw*.5); }
      } else {
        g.fill(hue,ox?26:12,(ox?12:18)*(.6+.5*near),100);
        g.rect(fx-fw,y-fh*.5,fw*2,fh);
        g.fill(hue,ox?22:10,(ox?26:46)*(.5+.6*near),100);
        g.rect(fx-fw,y-fh*.5,fw*2,Math.max(1,fh*.16));
        for(let q=0;q<6;q++){
          const by=y-fh*.40+q*fh*.16;
          g.fill(hue,8,(ox?30:58)*(.5+.6*near),90); g.ellipse(fx-fw*.45,by,fw*.55,fw*.55);
          g.fill(hue,8,10,70); g.ellipse(fx-fw*.45,by+fw*.16,fw*.42,fw*.30);
          g.fill(hue,8,(ox?26:50)*(.5+.6*near),90); g.ellipse(fx+fw*.45,by,fw*.55,fw*.55);
        }
      }
    }

    // ---- hangers: the bank has to be held up by something ------------------
    if(!xr){
      for(let k=0;k<2;k++){
        const hx=W*(.16+.68*fr(i*19+k*3.1));
        g.fill(hue,10,(ox?16:26)*(.5+.5*near),88);
        g.rect(hx-Math.max(.8,dia*.05),ay-BH*.62,Math.max(1.6,dia*.10),y-(ay-BH*.62));
        g.noFill(); g.stroke(hue,10,(ox?22:40)*(.5+.5*near),92);
        g.strokeWeight(Math.max(1,dia*.09));
        g.arc(hx,y,dia*1.26,dia*1.26,-.15,Math.PI+.15);
        g.noStroke();
      }
    }

    // ---- corrosion + drip staining, soaked in under the joints -------------
    if(!xr){
      const NC=Math.round(dec*(9+dens*7));
      for(let k=0;k<NC;k++){
        const cxp=W*fr(i*23+k*.61), q=fr(i*23+k*.61+1);
        const cyp=y-dia*.5+q*dia, rr=dia*(.16+fr(i*23+k*.61+2)*.5);
        g.fill(md(H-176,360),46+fr(i*23+k*.61+3)*22,16+fr(i*23+k*.61+4)*22,34);
        g.ellipse(cxp,cyp,rr*2.4,rr*1.5);
        g.fill(md(H-182,360),52,10,26);
        g.rect(cxp-rr*.22,cyp,rr*.44,dia*(.4+fr(i*23+k*.61+5)*1.1));
      }
    }
  }
  S.base=g; S.bk=bkey;
}
if(!S.runs) S.runs=layout();
image(S.base,0,0);

const rs=S.runs;
const dc=drawingContext, oldOp=dc.globalCompositeOperation;

// ---- live lighting, clipped to each tube so the bed is never touched -------
// (a set is scenery: it must NEVER paint an opaque panel over the bg slot)
if(!sche){
  for(let i=0;i<rs.length;i++){
    const r=rs[i], y=r.y, dia=r.dia, near=1-r.dep;
    dc.save();
    dc.beginPath(); dc.rect(-2,y-dia*.5,W+4,dia); dc.clip();

    // the mast shadow crossing the bank — darkens pipe, not background
    dc.globalCompositeOperation='source-over';
    const sg=dc.createLinearGradient(shx-shw,0,shx+shw,0);
    sg.addColorStop(0,'rgba(6,9,16,0)');
    sg.addColorStop(.5,'rgba(6,9,16,'+(0.40*AL*(.4+.5*near)).toFixed(3)+')');
    sg.addColorStop(1,'rgba(6,9,16,0)');
    dc.fillStyle=sg; dc.fillRect(shx-shw,y-dia*.5,shw*2,dia);

    // the raking specular running along the crown of the tube
    dc.globalCompositeOperation='lighter';
    const hy=y-dia*(.16-.24*(elev-.5));
    const rw=dia*(9+6*near), rh=dia*(.20+.16*elev);
    const spec=(0.34+0.42*glow)*AL*(.45+.65*near);
    dc.save(); dc.translate(lx,hy); dc.scale(rw,Math.max(1,rh));
    const rg2=dc.createRadialGradient(0,0,0,0,0,1);
    rg2.addColorStop(0, xr?'rgba(210,228,255,'+spec.toFixed(3)+')'
                       :(lag?'rgba(255,250,238,'+(spec*.72).toFixed(3)+')'
                       :(ox?'rgba(255,206,150,'+(spec*.66).toFixed(3)+')'
                       :'rgba(255,246,226,'+spec.toFixed(3)+')')));
    rg2.addColorStop(.45,'rgba(255,240,214,'+(spec*.24).toFixed(3)+')');
    rg2.addColorStop(1,'rgba(255,240,214,0)');
    dc.fillStyle=rg2; dc.beginPath(); dc.arc(0,0,1,0,TAU); dc.fill();
    dc.restore();

    // broad fill light so the whole bank sits in a soft pool, not a hard bar
    const bg2=dc.createLinearGradient(lx-W*.5,0,lx+W*.5,0);
    const fill=(0.05+0.09*glow)*AL*(.4+.6*near);
    bg2.addColorStop(0,'rgba(190,214,255,0)');
    bg2.addColorStop(.5,'rgba(214,230,255,'+fill.toFixed(3)+')');
    bg2.addColorStop(1,'rgba(190,214,255,0)');
    dc.fillStyle=bg2; dc.fillRect(lx-W*.5,y-dia*.5,W,dia);
    dc.restore();
  }
  dc.globalCompositeOperation=oldOp;
} else {
  // schematic: the signal itself is the motion — a bright pulse walks each header
  dc.globalCompositeOperation='lighter';
  noStroke();
  for(let i=0;i<rs.length;i++){
    const r=rs[i], y=r.y, dia=r.dia;
    const px=md(lx+i*W*.13,W*1.2)-W*.1;
    const gp=dc.createLinearGradient(px-W*.09,0,px+W*.09,0);
    const aa=(0.16+0.30*glow)*AL;
    gp.addColorStop(0,'rgba(90,200,255,0)');
    gp.addColorStop(.5,'rgba(150,224,255,'+aa.toFixed(3)+')');
    gp.addColorStop(1,'rgba(90,200,255,0)');
    dc.fillStyle=gp; dc.fillRect(px-W*.09,y-dia*.55,W*.18,dia*1.1);
  }
  dc.globalCompositeOperation=oldOp;
}

// ---- steam venting from a relief valve: a real process, above the band -----
if(act!=='cold'){
  dc.globalCompositeOperation='lighter';
  noStroke();
  const NV=Math.max(1,Math.round(1+dens*2));
  for(let v=0;v<NV;v++){
    const r=rs[Math.floor(fr(v*31)*rs.length)%rs.length];
    const vx=W*(.10+.80*fr(v*31+1)), vy=r.y-r.dia*.5;
    const surge=(act==='purge')?(.5+1.5*kick):1;
    const NP2=Math.round((7+dens*9)*(.5+.7*en));
    for(let k=0;k<NP2;k++){
      const ph=md(T*.077*(.7+.6*fr(v*31+k+2))+fr(v*31+k*.7+3),1);
      const rise=ph*BH*(.75+.5*en)*surge;
      const drift=(Math.sin(T*.23+k*1.7)*.5+Math.sin(T*.41+k)*.3)*BH*.16*ph;
      const rr=r.dia*(.30+ph*2.6)*surge;
      const aa=(1-ph)*(1-ph)*(0.05+0.10*glow)*AL;
      if(aa<=.002) continue;
      fill(md(H+10,360),cl(8-6*ph,0,20),cl(60+30*ph,0,100),aa*100);
      ellipse(vx+drift,vy-rise,rr*2.1,rr*1.7);
    }
  }
  dc.globalCompositeOperation=oldOp;
}

// ---- condensate drips off the low run -------------------------------------
if(!sche&&!xr){
  noStroke();
  const ND=Math.round(2+dens*4);
  for(let k=0;k<ND;k++){
    const r=rs[rs.length-1-(k%Math.min(2,rs.length))];
    const dx=W*(.06+.88*fr(k*37));
    const ph=md(T*.19+fr(k*37+1),1);
    const dy=r.y+r.dia*.5+ph*ph*BH*.55;
    fill(md(H+6,360),10,cl(58*glow+22,0,96),cl(58*(1-ph*.6),0,100)*AL);
    ellipse(dx,dy,r.dia*.13,r.dia*.13*(1+ph*1.6));
  }
}

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.globalAlpha=1; dc.shadowBlur=0;
noStroke(); noTint();
